import type {
  CodexAiResponsePayload,
  CodexJsonlRecord,
  CodexNormalizedEvent,
  CodexNormalizeResult,
  CodexSessionEndPayload,
  CodexUserPromptPayload,
} from './types.js';

const UNKNOWN_SESSION = 'unknown-session';

export function normalizeCodexRecords(records: readonly CodexJsonlRecord[]): CodexNormalizeResult {
  const events: CodexNormalizedEvent[] = [];
  let skipped = 0;
  let currentSessionId = UNKNOWN_SESSION;
  let currentProjectRoot = process.cwd();
  let currentModel: string | undefined;

  for (const record of records) {
    const raw = record.raw;
    const type = stringValue(raw.type);

    if (type === 'session_meta') {
      const meta = recordObject(raw.payload);
      currentSessionId =
        firstString(raw.session_id, meta?.session_id, meta?.id) ?? currentSessionId;
      currentProjectRoot = firstString(raw.cwd, meta?.cwd) ?? currentProjectRoot;
      currentModel = firstString(raw.model, meta?.model) ?? currentModel;

      events.push(
        createEvent(record, {
          kind: 'session_start',
          sessionId: currentSessionId,
          projectRoot: currentProjectRoot,
          payload: compactPayload({
            tool: 'codex',
            model: currentModel,
          }),
        }),
      );
      continue;
    }

    if (type === 'turn_context') {
      const turn = recordObject(raw.payload);
      currentProjectRoot = firstString(raw.cwd, turn?.cwd) ?? currentProjectRoot;
      currentModel = firstString(raw.model, turn?.model) ?? currentModel;
      skipped++;
      continue;
    }

    const sessionId = stringValue(raw.session_id) ?? currentSessionId;
    const projectRoot = stringValue(raw.cwd) ?? currentProjectRoot;

    if (type === 'event_msg') {
      const normalized = normalizeEventMessage(record, sessionId, projectRoot);
      if (normalized) {
        events.push(normalized);
      } else {
        skipped++;
      }
      continue;
    }

    if (type === 'response_item') {
      const normalized = normalizeResponseItem(record, sessionId, projectRoot, currentModel);
      if (normalized) {
        events.push(normalized);
      } else {
        skipped++;
      }
      continue;
    }

    skipped++;
  }

  return { events, skipped };
}

function normalizeEventMessage(
  record: CodexJsonlRecord,
  sessionId: string,
  projectRoot: string,
): CodexNormalizedEvent | undefined {
  const payloadRecord = recordObject(record.raw.payload);
  const event = payloadRecord ?? record.raw;
  const subtype = stringValue(record.raw.subtype) ?? stringValue(event.type);

  if (subtype === 'user_message') {
    const payload = {
      prompt: firstString(event.message, event.text) ?? '',
    } satisfies CodexUserPromptPayload;
    return createEvent(record, {
      kind: 'user_prompt',
      sessionId,
      projectRoot,
      payload,
    });
  }

  if (subtype === 'task_complete') {
    const summary = firstString(event.summary, event.last_agent_message, event.message, event.text);
    const payload = compactPayload({ summary }) as CodexSessionEndPayload;
    return createEvent(record, {
      kind: 'session_end',
      sessionId,
      projectRoot,
      payload,
    });
  }

  if (subtype === 'exec_command_end') {
    const exitCode = numberValue(event.exit_code);
    return createEvent(record, {
      kind: 'tool_use',
      sessionId,
      projectRoot,
      itemId: stringValue(event.call_id),
      payload: compactPayload({
        tool: 'exec_command_end',
        callId: stringValue(event.call_id),
        exitCode,
        durationMs: numberValue(event.duration_ms) ?? durationMsValue(event.duration),
        status: exitCode === undefined || exitCode === 0 ? 'success' : 'error',
      }),
    });
  }

  if (subtype === 'item_completed') {
    const item = recordObject(event.item);
    const itemType = stringValue(item?.type);

    if (itemType === 'UserMessage') {
      const prompt = extractTextContent(item?.content).trim();
      if (prompt.length === 0) {
        return undefined;
      }
      return createEvent(record, {
        kind: 'user_prompt',
        sessionId,
        projectRoot,
        itemId: stringValue(item?.id),
        payload: { prompt },
      });
    }

    if (itemType === 'CommandExecution') {
      const exitCode = numberValue(item?.exit_code);
      const rawStatus = stringValue(item?.status);
      const status =
        rawStatus === 'failed' || (exitCode !== undefined && exitCode !== 0) ? 'error' : 'success';
      return createEvent(record, {
        kind: 'tool_use',
        sessionId,
        projectRoot,
        itemId: stringValue(item?.id),
        payload: compactPayload({
          tool: 'CommandExecution',
          exitCode,
          durationMs: durationMsValue(item?.duration),
          status,
        }),
      });
    }

    return undefined;
  }

  return undefined;
}

function normalizeResponseItem(
  record: CodexJsonlRecord,
  sessionId: string,
  projectRoot: string,
  currentModel: string | undefined,
): CodexNormalizedEvent | undefined {
  const item = recordObject(record.raw.item) ?? recordObject(record.raw.payload);
  if (!item) {
    return undefined;
  }

  const itemType = stringValue(item.type);

  if (itemType === 'message' && stringValue(item.role) === 'assistant') {
    const payload = compactPayload({
      response: extractTextContent(item.content),
      model: currentModel,
    }) as CodexAiResponsePayload;
    return createEvent(record, {
      kind: 'ai_response',
      sessionId,
      projectRoot,
      payload,
    });
  }

  if (itemType === 'function_call') {
    const callId = stringValue(item.call_id);
    return createEvent(record, {
      kind: 'tool_use',
      sessionId,
      projectRoot,
      itemId: callId,
      payload: compactPayload({
        tool: stringValue(item.name) ?? 'function_call',
        callId,
        arguments: stringValue(item.arguments),
      }),
    });
  }

  if (itemType === 'function_call_output') {
    const callId = stringValue(item.call_id);
    return createEvent(record, {
      kind: 'tool_use',
      sessionId,
      projectRoot,
      itemId: callId,
      payload: compactPayload({
        tool: 'function_call_output',
        callId,
        output: stringValue(item.output),
      }),
    });
  }

  if (itemType === 'custom_tool_call') {
    const callId = stringValue(item.call_id);
    return createEvent(record, {
      kind: 'tool_use',
      sessionId,
      projectRoot,
      itemId: callId,
      payload: compactPayload({
        tool: stringValue(item.name) ?? 'custom_tool_call',
        callId,
        arguments: stringValue(item.input),
      }),
    });
  }

  if (itemType === 'custom_tool_call_output') {
    const callId = stringValue(item.call_id);
    const output = extractTextContent(item.output);
    return createEvent(record, {
      kind: 'tool_use',
      sessionId,
      projectRoot,
      itemId: callId,
      payload: compactPayload({
        tool: 'custom_tool_call_output',
        callId,
        output,
        status: inferToolOutputStatus(output),
      }),
    });
  }

  return undefined;
}

function inferToolOutputStatus(output: string): 'success' | 'error' {
  if (
    /(?:^\s*script\s+failed\b|\bscript\s+error:|\bexit\s+code:\s*(?:-[1-9]\d*|[1-9]\d*)|\bverification\s+failed\b|\baccess\s+is\s+denied\b|\brejected\s*\()/im.test(
      output,
    )
  ) {
    return 'error';
  }
  return 'success';
}

function createEvent(
  record: CodexJsonlRecord,
  input: Omit<CodexNormalizedEvent, 'sourceFile' | 'sourceLine' | 'timestamp'>,
): CodexNormalizedEvent {
  return {
    ...input,
    timestamp: timestampValue(record.raw.timestamp),
    sourceFile: record.filePath,
    sourceLine: record.line,
  };
}

function extractTextContent(value: unknown): string {
  if (typeof value === 'string') {
    return value;
  }

  if (!Array.isArray(value)) {
    return '';
  }

  return value
    .map((entry) => {
      if (typeof entry === 'string') {
        return entry;
      }

      if (!isRecordObject(entry)) {
        return undefined;
      }

      const text = stringValue(entry.text);
      if (text === undefined) {
        return undefined;
      }

      const type = stringValue(entry.type);
      return type === undefined ||
        type === 'output_text' ||
        type === 'input_text' ||
        type === 'text'
        ? text
        : undefined;
    })
    .filter((entry): entry is string => entry !== undefined)
    .join('\n');
}

function timestampValue(value: unknown): number {
  if (typeof value === 'number' && Number.isFinite(value)) {
    return value;
  }

  if (typeof value === 'string') {
    const parsed = Date.parse(value);
    if (Number.isFinite(parsed)) {
      return parsed;
    }
  }

  return Date.now();
}

function compactPayload(input: Record<string, unknown>): Record<string, unknown> {
  const output: Record<string, unknown> = {};
  for (const [key, value] of Object.entries(input)) {
    if (value !== undefined) {
      output[key] = value;
    }
  }
  return output;
}

function firstString(...values: unknown[]): string | undefined {
  for (const value of values) {
    const text = stringValue(value);
    if (text !== undefined) {
      return text;
    }
  }
  return undefined;
}

function recordObject(value: unknown): Record<string, unknown> | undefined {
  return isRecordObject(value) ? value : undefined;
}

function isRecordObject(value: unknown): value is Record<string, unknown> {
  return typeof value === 'object' && value !== null && !Array.isArray(value);
}

function stringValue(value: unknown): string | undefined {
  return typeof value === 'string' ? value : undefined;
}

function numberValue(value: unknown): number | undefined {
  return typeof value === 'number' && Number.isFinite(value) ? value : undefined;
}

function durationMsValue(value: unknown): number | undefined {
  const duration = recordObject(value);
  if (!duration) {
    return undefined;
  }

  const secs = numberValue(duration.secs);
  const nanos = numberValue(duration.nanos);
  if (secs === undefined && nanos === undefined) {
    return undefined;
  }

  return Math.round((secs ?? 0) * 1000 + (nanos ?? 0) / 1_000_000);
}
